  const platRaw = $('🔗 Obtener Plataformas G54').item.json;
  if (platRaw && platRaw.data && Array.isArray(platRaw.data) && platRaw.data.length > 0) {
    plataformas_conectadas = platRaw.data.map(p => p.platform || p.name || p).filter(Boolean);
  }
} catch(e) {
  // continueOnFail — usar fallback
}
const plataformas_str = plataformas_conectadas.join(', ');

// Leer métricas de rendimiento anteriores desde Analytics AI
let metricas_resumen = '';
try {
  const metricasRaw = $('📈 Obtener Métricas Anteriores G54').item.json;
  if (metricasRaw && metricasRaw.data && metricasRaw.data.length > 0) {
    const ultimas = metricasRaw.data.slice(0, 4);
    metricas_resumen = ultimas.map(m =>
      `- ${m.periodo} (${m.tipo}): ${m.metricas?.posts_publicados || 0} posts, ` +
      `${m.metricas?.leads_generados || 0} leads, ` +
      `mejor plataforma: ${m.metricas?.mejor_plataforma || 'N/A'}, ` +
      `mejor contenido: ${m.metricas?.mejor_tipo_contenido || 'N/A'}`
    ).join('\n');
  }
} catch(e) { /* sin métricas disponibles aún — continueOnFail */ }


